effect.shader:
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  vec2 p = uv * vec2(cols, rows) + vec2(0.0, acTime * scroll);
  vec2 g = abs(fract(p) - 0.5);
  vec2 l = smoothstep(0.5 - thickness, 0.5, g);
  float line = max(l.x, l.y);
  vec3 col = mix(c, lineColor.rgb, line * mixAmt);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0) * a, a);
}
